import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import LanguageDetector from 'i18next-browser-languagedetector';
import en from '../locales/en.json';
import ro from '../locales/ro.json';
import da from '../locales/da.json';

/**
 * Translations (i18next).
 *  - English is the source language: texts are written in src/locales/en.json,
 *    ro.json and da.json are generated by `npm run translate` (DeepL).
 *  - Language on first visit: the browser's language (ro/da/en), otherwise English.
 *    The visitor's choice is then remembered in localStorage ("anca-language").
 *  - In components: const { t } = useTranslation();  t('services.title')
 */
export const languages = ['en', 'ro', 'da'] as const;
export type Language = (typeof languages)[number];

export const languageOptions: { id: Language; label: string; flag: string }[] = [
    { id: 'ro', label: 'Română', flag: '🇷🇴' },
    { id: 'en', label: 'English', flag: '🇬🇧' },
    { id: 'da', label: 'Dansk', flag: '🇩🇰' },
];

i18n
    .use(LanguageDetector)
    .use(initReactI18next)
    .init({
        resources: {
            en: { translation: en },
            ro: { translation: ro },
            da: { translation: da },
        },
        supportedLngs: languages,
        fallbackLng: 'en',     // a missing text is shown in English
        load: 'languageOnly',  // "da-DK" → "da"
        detection: {
            order: ['localStorage', 'navigator'],
            lookupLocalStorage: 'anca-language',
            caches: ['localStorage'],
        },
        interpolation: { escapeValue: false }, // React already escapes
    });

// Keep <html lang> and the tab title in the current language.
function updateDocument() {
    document.documentElement.lang = i18n.resolvedLanguage ?? 'en';
    document.title = i18n.t('meta.title');
}
i18n.on('languageChanged', updateDocument);
updateDocument();

export default i18n;
